#!/usr/bin/env node
// seagent compat shim for an OpenClaw plugin (generated by `seagent-plugin::compat`).
//
// seagent's plugin protocol v1 is MCP JSON-RPC 2.0 over stdio, one object per line,
// no Content-Length framing (crates/seagent-plugin/src/plugin.rs,
// crates/seagent-plugin/src/transport.rs). This shim is plain Node, zero
// dependencies: it answers `initialize`, `tools/list`, `tools/call`,
// `seagent/hook` and `seagent/command`.
//
// The OpenClaw plugin itself is loaded best-effort: it imports
// `openclaw/plugin-sdk` (and the compiled `dist/*.mjs` runtime chunk), which seagent
// does not ship, so the import usually throws. When it does load, only the
// registrations an entry can make through a plain `register(api)` call are
// honoured (tools, commands); every other API is a no-op that is reported as
// unsupported. The manifest's own declarations (cliCommands, contracts) are
// answered from here, not from the plugin.
"use strict";

const ID = __ID__;
const MANIFEST = __MANIFEST__; // {name, description, cliCommands, contracts, hooks}
const PLUGIN_DIR = process.env.SEAGENT_PLUGIN_DIR || __PLUGIN_DIR__;

const log = (m) => {
  try {
    process.stderr.write(`seagent-compat[${ID}]: ${m}\n`);
  } catch {}
};
const send = (o) => {
  process.stdout.write(JSON.stringify(o) + "\n");
};
const reply = (id, result) => send({ jsonrpc: "2.0", id, result });
const fail = (id, code, message) => send({ jsonrpc: "2.0", id, error: { code, message } });

const tools = new Map(); // name -> {handler, description}
const commands = new Map(); // name -> {handler, description}
const hooks = new Map(); // event -> [handler]
const unsupported = new Set();

// Everything seagent (or a well-meaning plugin) may call on an OpenClaw `api`.
function stubApi() {
  const record = (kind) => (...args) => {
    unsupported.add(kind);
    return undefined;
  };
  const api = {
    pluginConfig: {},
    logger: { info: log, warn: log, error: log, debug: () => {} },
    registerTool(name, def, handler) {
      const fn = typeof def === "function" ? def : handler;
      tools.set(String(name), { handler: typeof fn === "function" ? fn : null, description: (def && def.description) || "" });
    },
    registerCommand(name, def, handler) {
      const fn = typeof def === "function" ? def : handler;
      commands.set(String(name), { handler: typeof fn === "function" ? fn : null, description: (def && def.description) || "" });
    },
    on(event, handler) {
      if (typeof handler === "function") {
        const k = String(event);
        if (!hooks.has(k)) hooks.set(k, []);
        hooks.get(k).push(handler);
      }
    },
  };
  // Any other capability (gateway methods, channels, providers, HTTP routes,
  // context engines, node commands, UI) has no seagent equivalent: accept and note.
  return new Proxy(api, {
    get(t, k) {
      if (k in t) return t[k];
      if (typeof k === "symbol") return undefined;
      return record(String(k));
    },
  });
}

async function loadPlugin() {
  const extra = Array.isArray(MANIFEST.entries) ? MANIFEST.entries.filter((e) => typeof e === "string") : [];
  const candidates = [...new Set([...extra, "index.mjs", "index.js", "index.cjs"])];
  for (const f of candidates) {
    const rel = f.replace(/^\.\//, "");
    // A real file URL: `file:///C:/x/index.js` on Windows (and spaces / `#` escaped anywhere).
    const { pathToFileURL } = await import("node:url");
    const { join } = await import("node:path");
    const url = pathToFileURL(join(PLUGIN_DIR, rel)).href;
    let mod;
    try {
      mod = await import(url);
    } catch (e) {
      log(`cannot load ${f}: ${e && e.message ? e.message : e}`);
      continue;
    }
    const entry = mod && (mod.default || mod.plugin || mod);
    const register = entry && typeof entry.register === "function" ? entry.register : entry && typeof entry.activate === "function" ? entry.activate : null;
    if (!register) {
      log(`${f} does not export a register(api) entry; running as a declaration-only plugin`);
      return;
    }
    try {
      await register(stubApi());
      log(`loaded ${f}; registered ${tools.size} tool(s), ${commands.size} command(s), ${hooks.size} hook event(s)`);
    } catch (e) {
      log(`register(api) failed, continuing without the plugin's own handlers: ${e && e.message ? e.message : e}`);
    }
    return;
  }
  log("no index.js/index.mjs in the plugin directory");
}

// The manifest's `cliCommands` are answered here even when the plugin never loads:
// seagent sees the command, and a call explains that the runtime is missing.
function declareManifestCommands() {
  for (const c of Array.isArray(MANIFEST.cliCommands) ? MANIFEST.cliCommands : []) {
    const name = c && typeof c.name === "string" ? c.name : "";
    if (name && !commands.has(name)) commands.set(name, { handler: null, description: c.description || "", declared: true });
  }
}

const text = (v) => (typeof v === "string" ? v : JSON.stringify(v));

function decisionOf(r) {
  if (r == null) return { decision: "allow" };
  if (typeof r !== "object") return { decision: "allow" };
  if (["allow", "deny", "modify"].includes(r.decision)) {
    const out = { decision: r.decision };
    if (typeof r.reason === "string") out.reason = r.reason;
    if ("input" in r) out.input = r.input;
    return out;
  }
  if (r.blocked === true || r.action === "block" || r.action === "deny") {
    return { decision: "deny", reason: typeof r.reason === "string" ? r.reason : "blocked by plugin" };
  }
  return { decision: "allow" };
}

async function handle(method, params) {
  switch (method) {
    case "initialize": {
      const caps = {};
      if (tools.size) caps.tools = {};
      caps.experimental = {
        seagent: {
          version: 1,
          hooks: [...hooks.keys()],
          commands: [...commands.entries()].map(([name, c]) => ({ name, description: c.description || "", args: "" })),
        },
      };
      return { protocolVersion: typeof params.protocolVersion === "string" ? params.protocolVersion : "2025-11-25", capabilities: caps, serverInfo: { name: ID, version: "compat-shim" } };
    }
    case "ping":
    case "shutdown":
      return {};
    case "tools/list":
      return { tools: [...tools.entries()].map(([name, t]) => ({ name, description: t.description || "", inputSchema: { type: "object", additionalProperties: true } })) };
    case "tools/call": {
      const name = String(params.name || "");
      const t = tools.get(name);
      if (!t || !t.handler) return { content: [{ type: "text", text: `tool ${name} is not exported by this plugin` }], isError: true };
      try {
        return { content: [{ type: "text", text: text(await t.handler(params.arguments || {})) }] };
      } catch (e) {
        return { content: [{ type: "text", text: `tool ${name} failed: ${e && e.message ? e.message : e}` }], isError: true };
      }
    }
    case "seagent/hook": {
      const fns = hooks.get(String(params.event || "")) || [];
      for (const fn of fns) {
        try {
          const d = decisionOf(await fn(params.payload || {}));
          if (d.decision !== "allow") return d;
        } catch (e) {
          log(`hook ${params.event} failed (allowing): ${e && e.message ? e.message : e}`);
        }
      }
      return { decision: "allow" };
    }
    case "seagent/command": {
      const name = String(params.name || "").replace(/^\//, "");
      const c = commands.get(name);
      if (!c || !c.handler) return { text: `command \`${name}\` is declared by the manifest but not implemented by the plugin: ${unsupported.size ? "OpenClaw runtime APIs are unavailable in seagent" : "no handler registered"}` };
      try {
        const r = await c.handler(params.args || "");
        return r == null ? {} : { text: text(r) };
      } catch (e) {
        return { text: `command \`${name}\` failed: ${e && e.message ? e.message : e}` };
      }
    }
    case "resources/list":
      return { resources: [] };
    case "prompts/list":
      return { prompts: [] };
    default: {
      const e = new Error(`method not found: ${method}`);
      e.code = -32601;
      throw e;
    }
  }
}

async function main() {
  await loadPlugin();
  declareManifestCommands();
  let buf = "";
  process.stdin.setEncoding("utf8");
  for await (const chunk of process.stdin) {
    buf += chunk;
    let i;
    while ((i = buf.indexOf("\n")) >= 0) {
      const line = buf.slice(0, i).trim();
      buf = buf.slice(i + 1);
      if (!line) continue;
      let msg;
      try {
        msg = JSON.parse(line);
      } catch {
        log("ignoring a line that is not JSON");
        continue;
      }
      if (!msg || typeof msg !== "object" || msg.method === undefined) continue;
      if (msg.id === undefined || msg.id === null) continue; // notification
      try {
        reply(msg.id, await handle(String(msg.method), msg.params || {}));
      } catch (e) {
        if (e && e.code === -32601) fail(msg.id, -32601, e.message);
        else fail(msg.id, -32603, String((e && e.message) || e));
      }
    }
  }
}

main().catch((e) => {
  log(`shim failed: ${e && e.message ? e.message : e}`);
  process.exit(1);
});
